(()=>{
 // Warm a small number of real linked documents, without loading every portfolio image or PDF.
 const network=navigator.connection;const constrained=network?.saveData||/^(slow-)?2g$/.test(network?.effectiveType||'');const seen=new Set();const maxPages=8;
 function destination(anchor){if(!anchor||anchor.hasAttribute('download')||anchor.target==='_blank')return null;let url;try{url=new URL(anchor.href,location.href);}catch{return null;}if(url.origin!==location.origin||url.pathname===location.pathname||url.pathname.startsWith('/assets/')||/\.[a-z0-9]+$/i.test(url.pathname)||url.search)return null;return url.origin+url.pathname;}
 function prefetch(anchor){if(constrained||document.visibilityState==='hidden'||seen.size>=maxPages)return;const href=destination(anchor);if(!href||seen.has(href))return;seen.add(href);const link=document.createElement('link');link.rel='prefetch';link.as='document';link.href=href;link.fetchPriority='low';document.head.append(link);}
 let hoverTimer;document.addEventListener('pointerover',e=>{const a=e.target.closest('a[href]');clearTimeout(hoverTimer);if(a)hoverTimer=setTimeout(()=>prefetch(a),120);},{passive:true});document.addEventListener('focusin',e=>prefetch(e.target.closest('a[href]')));
 const idle=window.requestIdleCallback||((fn)=>setTimeout(fn,1200));idle(()=>{const anchors=[...document.querySelectorAll('.portfolio-project-card[href],.simple-project a[href]')].filter(a=>destination(a)).slice(0,3);anchors.forEach((a,i)=>setTimeout(()=>prefetch(a),i*350));});
 // Clear active-state feedback for every inline section navigator.
 document.querySelectorAll('.library-tabs').forEach(nav=>{const entries=[...nav.querySelectorAll('a[href^="#"]')].map(a=>({a,section:document.getElementById(decodeURIComponent(a.hash.slice(1)))})).filter(x=>x.section);if(!entries.length)return;function active(entry){entries.forEach(x=>x.a.removeAttribute('aria-current'));entry.a.setAttribute('aria-current','true');}active(entries.find(x=>x.a.hash===location.hash)||entries[0]);entries.forEach(entry=>entry.a.addEventListener('click',()=>{active(entry);nav.scrollTo({left:Math.max(0,nav.scrollLeft+entry.a.getBoundingClientRect().left-nav.getBoundingClientRect().left-12),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}));if('IntersectionObserver' in window){const observer=new IntersectionObserver(items=>{const visible=items.filter(x=>x.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top)[0];if(visible){const entry=entries.find(x=>x.section===visible.target);if(entry)active(entry);}},{rootMargin:'-15% 0px -65% 0px',threshold:0});entries.forEach(x=>observer.observe(x.section));}});
})();
